"use strict";
var D = window.__MF_GAME__;
if (!D) { document.body.innerHTML = '<p style="color:#fff;font-family:sans-serif">Minesword runtime: missing game data (window.__MF_GAME__).</p>'; return; }

/* ==========================================================================
   FREE vs PRO TIER — this is the ONE flag that should change between the
   free download of Minesword Forge and a separately-built Pro edition.
   When true, exported games show the boot splash (see _mfBootGate below)
   and re-verify every ~1.5s that it actually ran correctly (see _mfWatch /
   _mfCheckIntegrity). A Pro build of the EDITOR app should set this to
   false before building — not something exposed as a project setting or a
   runtime toggle in the free app, since anything a user (or an AI they ask
   to edit their exported game) can flip themselves back to false isn't
   actually gating anything. Real enforcement is "which build of the app
   you got it from", the same way a paid/free pair of Android apps are two
   separate APKs rather than one APK with an unlock checkbox.
   ========================================================================== */
var MF_FREE_TIER = true;

/* ---------- on-screen error overlay ----------
   There's no devtools console on a phone, so any uncaught error (here, or in a
   user script) gets written to a small on-screen panel instead of only the
   invisible browser console — tap the bug icon to open/close it. */
var mfErrLog = [];
var mfErrBox = null, mfErrList = null, mfErrBtn = null;
function mfShowError(msg) {
  mfErrLog.push('[' + new Date().toLocaleTimeString() + '] ' + msg);
  if (mfErrLog.length > 40) mfErrLog.shift();
  if (!mfErrBtn) {
    mfErrBtn = document.createElement('div');
    mfErrBtn.textContent = '⚠ ' + mfErrLog.length;
    mfErrBtn.style.cssText = 'position:fixed;left:8px;top:8px;z-index:2147483647;background:#ff4d4f;color:#fff;font:700 12px/1 -apple-system,sans-serif;padding:7px 10px;border-radius:16px;box-shadow:0 2px 8px rgba(0,0,0,.4);cursor:pointer;';
    mfErrBtn.addEventListener('click', function () { mfErrBox.style.display = mfErrBox.style.display === 'none' ? 'block' : 'none'; });
    document.body.appendChild(mfErrBtn);
    mfErrBox = document.createElement('div');
    mfErrBox.style.cssText = 'display:none;position:fixed;left:8px;top:44px;right:8px;max-height:70vh;overflow:auto;z-index:2147483647;background:rgba(15,17,22,.96);color:#ffb4b4;font:11px/1.5 "IBM Plex Mono",monospace;padding:10px;border-radius:8px;border:1px solid #ff4d4f;white-space:pre-wrap;word-break:break-word;';
    document.body.appendChild(mfErrBox);
  } else {
    mfErrBtn.textContent = '⚠ ' + mfErrLog.length;
  }
  mfErrBox.textContent = mfErrLog.join('\n\n');
}
window.addEventListener('error', function (e) {
  mfShowError((e.message || 'Error') + (e.filename ? ' — ' + e.filename.split('/').pop() + ':' + e.lineno : ''));
});
window.addEventListener('unhandledrejection', function (e) {
  mfShowError('Unhandled promise rejection: ' + (e.reason && e.reason.message ? e.reason.message : String(e.reason)));
});

